BEGIN;
SET LOCAL search_path=public,extensions;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
DO $test$
DECLARE c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();w uuid:=gen_random_uuid();other uuid:=gen_random_uuid();
 p uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();p3 uuid:=gen_random_uuid();m uuid;renewed uuid;
 result jsonb;terms jsonb;charge jsonb;version timestamptz;expired timestamptz:=now()-interval '1 second';
BEGIN
 INSERT INTO campuses(id,name,slug) VALUES(c,'[ROLLBACK] Delivery pass',c::text),(c2,'[ROLLBACK] Other pass campus',c2::text);
 INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT x,'pass-test-'||x||'@example.invalid','{}' FROM unnest(ARRAY[a,u,v,w,other])x;
 UPDATE profiles SET role='student',campus_id=c,is_active=true WHERE id IN(u,v,w);
 UPDATE profiles SET role='admin',campus_id=c,is_active=true WHERE id=a;
 UPDATE profiles SET role='admin',campus_id=c2,is_active=true WHERE id=other;
 INSERT INTO wallets(user_id,balance) VALUES(u,1000),(v,0),(w,0) ON CONFLICT(user_id) DO UPDATE SET balance=excluded.balance;
 result:=hg_delivery_pass(a,'configure',NULL,jsonb_build_object('campus_id',c,'price_kobo',10000,'is_active',true));version:=(result->>'updated_at')::timestamptz;
 terms:=jsonb_build_object('method','wallet','price_kobo',10000,'auto_renew',false,'ledger_reason','Test pass purchase');
 BEGIN PERFORM hg_delivery_pass(u,'buy',p,terms);RAISE EXCEPTION 'disabled sale allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_unavailable' THEN RAISE;END IF;END;
 INSERT INTO feature_flags(feature_name,is_active,campus_id) VALUES('delivery_pass',true,c);
 BEGIN PERFORM hg_delivery_pass(other,'report',NULL,jsonb_build_object('campus_id',c));RAISE EXCEPTION 'foreign campus report';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM hg_delivery_pass(u,'configure',NULL,jsonb_build_object('campus_id',c,'price_kobo',10000,'is_active',true));RAISE EXCEPTION 'customer config';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE admin_audit_logs SET created_at=now()-interval '3 hours' WHERE entity_type='cron_jobs' AND entity_id='delivery-pass-renewals' AND action='scheduled_execution_success';
 BEGIN PERFORM hg_delivery_pass(u,'buy',p,terms||jsonb_build_object('auto_renew',true,'consent_version','delivery-pass-wallet-v1'));RAISE EXCEPTION 'renewal accepted without worker';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_renewal_unavailable' THEN RAISE;END IF;END;
 INSERT INTO admin_audit_logs(actor_role,entity_type,entity_id,action,after_value) VALUES('system','cron_jobs','delivery-pass-renewals','scheduled_execution_success','{}');
 terms:=terms||jsonb_build_object('auto_renew',true,'consent_version','delivery-pass-wallet-v1');
 result:=hg_delivery_pass(u,'buy',p,terms);m:=(result->>'membership_id')::uuid;
 IF result->>'status'<>'paid' OR (SELECT balance FROM wallets WHERE user_id=u)<>900 THEN RAISE EXCEPTION 'wallet pass debit';END IF;
 IF (result->>'period_until')::timestamptz IS DISTINCT FROM (result->>'period_from')::timestamptz+interval '1 month' THEN RAISE EXCEPTION 'calendar month period';END IF;
 result:=hg_delivery_pass(u,'buy',p,terms);
 IF result->>'replayed'<>'true' OR (SELECT balance FROM wallets WHERE user_id=u)<>900 THEN RAISE EXCEPTION 'duplicate wallet debit';END IF;
 BEGIN PERFORM hg_delivery_pass(u,'buy',p,terms||'{"method":"card"}');RAISE EXCEPTION 'changed intent accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_conflict' THEN RAISE;END IF;END;
 BEGIN PERFORM hg_delivery_pass(u,'buy',gen_random_uuid(),terms);RAISE EXCEPTION 'active duplicate purchase';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_already_active' THEN RAISE;END IF;END;
 BEGIN PERFORM hg_delivery_pass(v,'receipt',p);RAISE EXCEPTION 'foreign receipt read';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE feature_flags SET is_active=false WHERE feature_name='delivery_pass' AND campus_id=c;
 IF NOT (hg_delivery_pass(u,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id') THEN RAISE EXCEPTION 'paused sales removed paid coverage';END IF;
 UPDATE feature_flags SET is_active=true WHERE feature_name='delivery_pass' AND campus_id=c;
 result:=hg_delivery_pass(a,'configure',NULL,jsonb_build_object('campus_id',c,'price_kobo',20000,'is_active',true,'expected_updated_at',version));
 BEGIN PERFORM hg_delivery_pass(a,'configure',NULL,jsonb_build_object('campus_id',c,'price_kobo',30000,'is_active',true,'expected_updated_at',version));RAISE EXCEPTION 'stale offer overwritten';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_conflict' THEN RAISE;END IF;END;
 UPDATE hg_internal.delivery_pass_memberships SET paid_until=expired WHERE id=m;
 UPDATE hg_internal.delivery_pass_receipts SET period_until=expired WHERE id=p;
 IF hg_delivery_pass(u,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id' THEN RAISE EXCEPTION 'expired benefit';END IF;
 result:=hg_delivery_pass(NULL,'renew',m,'{"ledger_reason":"Test monthly renewal"}');renewed:=(result->>'id')::uuid;
 IF result->>'status'<>'paid' OR (result->>'amount_kobo')::integer<>10000 OR (SELECT balance FROM wallets WHERE user_id=u)<>800 THEN RAISE EXCEPTION 'agreed renewal price/debit';END IF;
 PERFORM hg_delivery_pass(NULL,'renew',m,'{"ledger_reason":"Test monthly renewal"}');
 IF (SELECT balance FROM wallets WHERE user_id=u)<>800 THEN RAISE EXCEPTION 'renewal replay charged twice';END IF;
 result:=hg_delivery_pass(a,'refund',renewed,'{"reason":"Support-approved refund","ledger_reason":"Test wallet refund"}');
 IF result->>'status'<>'refunded' OR (SELECT balance FROM wallets WHERE user_id=u)<>900 OR hg_delivery_pass(u,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id' THEN RAISE EXCEPTION 'refund coverage/debit conservation';END IF;
 PERFORM hg_delivery_pass(a,'refund',renewed,'{"reason":"Retry refund","ledger_reason":"Test wallet refund"}');
 IF (SELECT balance FROM wallets WHERE user_id=u)<>900 THEN RAISE EXCEPTION 'refund replay credited twice';END IF;
 BEGIN PERFORM hg_delivery_pass(u,'refund',p,'{"reason":"Customer request","ledger_reason":"No permission"}');RAISE EXCEPTION 'self refund allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 result:=hg_delivery_pass(u,'buy',gen_random_uuid(),terms||'{"price_kobo":20000}');
 UPDATE hg_internal.delivery_pass_memberships SET paid_until=expired WHERE id=m;
 UPDATE wallets SET balance=0 WHERE user_id=u;
 PERFORM hg_delivery_pass(NULL,'renew',m,'{"ledger_reason":"Test failed renewal"}');
 IF (SELECT auto_renew FROM hg_internal.delivery_pass_memberships WHERE id=m) OR (SELECT balance FROM wallets WHERE user_id=u)<>0 THEN RAISE EXCEPTION 'unfunded renewal';END IF;
 UPDATE wallets SET balance=500 WHERE user_id=u;
 PERFORM hg_delivery_pass(NULL,'renew',m,'{"ledger_reason":"No surprise retry"}');
 IF (SELECT balance FROM wallets WHERE user_id=u)<>500 THEN RAISE EXCEPTION 'surprise debit after funding';END IF;
 result:=hg_delivery_pass(v,'buy',p2,'{"method":"card","price_kobo":20000,"auto_renew":false}');
 IF result->>'status'<>'pending' OR hg_delivery_pass(v,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id' THEN RAISE EXCEPTION 'card initialized as paid';END IF;
 charge:=jsonb_build_object('reference','HG-PASS-'||p2::text,'amount_kobo',20300,'fees_kobo',300,'requested_amount_kobo',20000,'currency','NGN','ledger_reason','Test recovery');
 BEGIN PERFORM hg_delivery_pass(NULL,'confirm',p2,charge||'{"amount_kobo":1000}');RAISE EXCEPTION 'underpaid pass accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'pass_payment_mismatch' THEN RAISE;END IF;END;
 result:=hg_delivery_pass(NULL,'confirm',p2,charge);
 IF result->>'status'<>'paid' OR NOT(hg_delivery_pass(v,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id') OR (SELECT balance FROM wallets WHERE user_id=v)<>0 THEN RAISE EXCEPTION 'verified card did not grant pass';END IF;
 PERFORM hg_delivery_pass(NULL,'confirm',p2,charge);
 IF (SELECT count(*) FROM hg_internal.delivery_pass_receipts WHERE id=p2)<>1 THEN RAISE EXCEPTION 'duplicate card receipt';END IF;
 result:=hg_delivery_pass(w,'buy',p3,'{"method":"card","price_kobo":20000,"auto_renew":false}');
 PERFORM hg_delivery_pass(w,'cancel',p3);
 charge:=charge||jsonb_build_object('reference','HG-PASS-'||p3::text);
 result:=hg_delivery_pass(NULL,'confirm',p3,charge);
 PERFORM hg_delivery_pass(NULL,'confirm',p3,charge);
 IF result->>'status'<>'credited' OR (SELECT balance FROM wallets WHERE user_id=w)<>200 OR hg_delivery_pass(w,'benefit',NULL,jsonb_build_object('campus_id',c)) ? 'id' THEN RAISE EXCEPTION 'late payment lost/duplicated';END IF;
 IF has_function_privilege('anon','public.hg_delivery_pass(uuid,text,uuid,jsonb)','execute') OR has_function_privilege('authenticated','public.hg_delivery_pass(uuid,text,uuid,jsonb)','execute') THEN RAISE EXCEPTION 'public financial helper';END IF;
 result:=hg_delivery_pass(a,'report',NULL,jsonb_build_object('campus_id',c));
 IF (result->>'active_members')::integer<>1 OR (result->>'refunds_kobo')::integer<>10000 THEN RAISE EXCEPTION 'pass report reconciliation';END IF;
 -- Paused campuses do not starve the shared renewal queue; old consent is retired.
 UPDATE hg_internal.delivery_pass_memberships SET auto_renew=true,consent_version='delivery-pass-wallet-v1',consented_at=now(),paid_until=now()-interval '1 hour' WHERE id=m;
 UPDATE feature_flags SET is_active=false WHERE feature_name='delivery_pass' AND campus_id=c;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(hg_delivery_pass(NULL,'scan')->'due')x WHERE x->>'id'=m::text) THEN RAISE EXCEPTION 'paused campus occupies renewal queue';END IF;
 UPDATE hg_internal.delivery_pass_memberships SET paid_until=now()-interval '3 days' WHERE id=m;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(hg_delivery_pass(NULL,'scan')->'due')x WHERE x->>'id'=m::text) THEN RAISE EXCEPTION 'overdue consent not retired';END IF;
 PERFORM hg_delivery_pass(NULL,'renew',m,'{}');
 IF (SELECT auto_renew FROM hg_internal.delivery_pass_memberships WHERE id=m) THEN RAISE EXCEPTION 'overdue consent still active';END IF;
END$test$;
SELECT 'PASS monthly wallet/card entitlement, fixed-price renewal, heartbeat/consent, replay, failed renewal, closed-loop refund, late payment recovery and role/campus boundaries' AS verified;
ROLLBACK;
